// Retrieve the topic and the AI's generated report summary text
const topic = $input.item.json.research_topic || "AI Web Research Summary";
const markdownContent = $input.item.json.output || "No report generated.";

// Convert basic markdown paragraphs and bold tags to HTML elements for readability
let formattedBody = markdownContent
  .replace(/\n\n/g, '</p><p>')
  .replace(/\n/g, '<br>')
  .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');

// Generate a professional styled production-grade HTML layout
const htmlReport = `
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Research Report: ${topic}</title>
    <style>
        body { font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; line-height: 1.6; color: #333; max-width: 800px; margin: 0 auto; padding: 40px 20px; background-color: #f9f9f9; }
        .report-card { background: white; padding: 40px; border-radius: 12px; box-shadow: 0 4px 15px rgba(0,0,0,0.05); border-top: 8px solid #0052cc; }
        h1 { color: #0052cc; font-size: 2.5em; margin-bottom: 10px; border-bottom: 2px solid #eaeaea; padding-bottom: 15px; }
        .timestamp { color: #777; font-size: 0.9em; margin-bottom: 30px; font-style: italic; }
        p { margin-bottom: 20px; font-size: 1.1em; color: #4a4a4a; }
        strong { color: #111; }
    </style>
</head>
<body>
    <div class="report-card">
        <h1>Research Report: ${topic}</h1>
        <div class="timestamp">Generated autonomously via AI Research Agent on: ${new Date().toLocaleDateString()}</div>
        <p>${formattedBody}</p>
    </div>
</body>
</html>
`;

return [{ json: { html_report: htmlReport } }];
